3	import com.example.starter.firmware.domain.ReceiptResult;
4	import com.example.starter.firmware.domain.ReleaseOrder;
5	import com.example.starter.firmware.domain.ReleaseStatus;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.jdbc.core.RowMapper;
8	import org.springframework.jdbc.support.GeneratedKeyHolder;
9	import org.springframework.jdbc.support.KeyHolder;
10	import org.springframework.stereotype.Repository;
11	
12	import java.sql.PreparedStatement;
13	import java.util.Optional;
14	
15	/**
16	 * 发布单数据访问。扩量、取消、恢复、拉取、回执共用行锁（SELECT ... FOR UPDATE）形成一致提交顺序。
17	 * 当前轮次统计（round_success/round_failed）只在持有发布单行锁的事务内增减。
18	 */
19	@Repository
20	public class ReleaseRepository {
21	
22	    private static final RowMapper<ReleaseOrder> MAPPER = (rs, rowNum) -> new ReleaseOrder(
23	            rs.getLong("id"), rs.getInt("version"), rs.getString("model"),
24	            rs.getString("from_version"), rs.getString("to_version"),
25	            rs.getInt("ratio"), ReleaseStatus.valueOf(rs.getString("status")),
26	            rs.getInt("sample_floor"), rs.getInt("failure_threshold_percent"),
27	            rs.getInt("monitor_round"), rs.getInt("round_success"), rs.getInt("round_failed"));
28	
29	    private static final String COLUMNS = "id, version, model, from_version, to_version, ratio, status,"
30	            + " sample_floor, failure_threshold_percent, monitor_round, round_success, round_failed";
31	
32	    private final JdbcTemplate jdbc;
33	
34	    public ReleaseRepository(JdbcTemplate jdbc) {
35	        this.jdbc = jdbc;
36	    }
37	
38	    public long insert(String model, String fromVersion, String toVersion, int ratio,
39	                       int sampleFloor, int failureThresholdPercent) {
40	        KeyHolder keyHolder = new GeneratedKeyHolder();
41	        jdbc.update(con -> {
42	            PreparedStatement ps = con.prepareStatement(
43	                    "INSERT INTO release_order (version, model, from_version, to_version, ratio, status,"
44	                            + " sample_floor, failure_threshold_percent, monitor_round, active_model)"
45	                            + " VALUES (1, ?, ?, ?, ?, 'ACTIVE', ?, ?, 1, ?)",
46	                    new String[]{"id"});
47	            ps.setString(1, model);
48	            ps.setString(2, fromVersion);
49	            ps.setString(3, toVersion);
50	            ps.setInt(4, ratio);
51	            ps.setInt(5, sampleFloor);
52	            ps.setInt(6, failureThresholdPercent);
53	            ps.setString(7, model);
54	            return ps;
55	        }, keyHolder);
56	        return keyHolder.getKey().longValue();
57	    }
58	
59	    public Optional<ReleaseOrder> findById(long id) {
60	        return jdbc.query("SELECT " + COLUMNS + " FROM release_order WHERE id = ?", MAPPER, id)
61	                .stream().findFirst();
62	    }
63	
64	    public Optional<ReleaseOrder> findByIdForUpdate(long id) {
65	        return jdbc.query("SELECT " + COLUMNS + " FROM release_order WHERE id = ? FOR UPDATE", MAPPER, id)
66	                .stream().findFirst();
67	    }
68	
69	    /**
70	     * 按型号查找未终结（ACTIVE 或 PAUSED）发布单；active_model 唯一约束保证至多一条。
71	     */
72	    public Optional<ReleaseOrder> findActiveByModel(String model) {
73	        return jdbc.query("SELECT " + COLUMNS + " FROM release_order WHERE active_model = ?", MAPPER, model)
74	                .stream().findFirst();
75	    }
76	
77	    /**
78	     * 乐观扩量：仅当版本与状态匹配时生效，返回影响行数。
79	     */
80	    public int expand(long id, int expectedVersion, int newRatio) {
81	        return jdbc.update("UPDATE release_order SET version = version + 1, ratio = ?, updated_at = CURRENT_TIMESTAMP"
82	                + " WHERE id = ? AND version = ? AND status = 'ACTIVE'", newRatio, id, expectedVersion);
83	    }
84	
85	    public void cancel(long id) {
86	        jdbc.update("UPDATE release_order SET status = 'CANCELLED', active_model = NULL,"
87	                + " updated_at = CURRENT_TIMESTAMP WHERE id = ?", id);
88	    }
89	
90	    /**
91	     * 当前监控轮次统计加一（成功或失败），调用方必须已持有发布单行锁。
92	     */
93	    public void incrementRoundStats(long id, ReceiptResult result) {
94	        if (result == ReceiptResult.SUCCESS) {
95	            jdbc.update("UPDATE release_order SET round_success = round_success + 1,"
96	                    + " updated_at = CURRENT_TIMESTAMP WHERE id = ?", id);
97	        } else {
98	            jdbc.update("UPDATE release_order SET round_failed = round_failed + 1,"
99	                    + " updated_at = CURRENT_TIMESTAMP WHERE id = ?", id);
100	        }
101	    }
102	
103	    /**
104	     * 仅当仍为 ACTIVE 时转为 PAUSED，返回影响行数；调用方已持有行锁，并发回执至多一行生效。
105	     */
106	    public int pauseIfActive(long id) {
107	        return jdbc.update("UPDATE release_order SET status = 'PAUSED', updated_at = CURRENT_TIMESTAMP"
108	                + " WHERE id = ? AND status = 'ACTIVE'", id);
109	    }
110	
111	    /**
112	     * 人工恢复：仅当版本匹配且仍为 PAUSED 时生效；版本加一、开启新监控轮次并清零本轮统计。
113	     */
114	    public int resume(long id, int expectedVersion) {
115	        return jdbc.update("UPDATE release_order SET status = 'ACTIVE', version = version + 1,"
116	                + " monitor_round = monitor_round + 1, round_success = 0, round_failed = 0,"
117	                + " updated_at = CURRENT_TIMESTAMP"
118	                + " WHERE id = ? AND version = ? AND status = 'PAUSED'", id, expectedVersion);
119	    }
120	}
