    @Test
    void 拉取_不匹配不创建任务_重复拉取返回已有任务() throws Exception {
        registerDevice("r1", "d1", "m1", "1.0.0", 50);
        registerDevice("r2", "d2", "m1", "9.9.9", 1);
        createRelease("r3", "m1", "1.0.0", "2.0.0", 10);

