    @Test
    void 取消_未终结任务转CANCELLED_后到回执409且不更新版本() throws Exception {
        registerDevice("r1", "d1", "m1", "1.0.0", 1);
        registerDevice("r2", "d2", "m1", "1.0.0", 2);
        long releaseId = releaseIdOf(createRelease("r3", "m1", "1.0.0", "2.0.0", 100));
