138	        List<Callable<Object>> tasks = new ArrayList<>();
139	        for (int i = 0; i < 2; i++) {
140	            int seq = i;
141	            tasks.add(() -> releaseService.create(
142	                    new CreateReleaseRequest("req-c" + seq, "m1", "1.0.0", "2.0.0", 10)).releaseId());
143	        }
144	        List<Object> results = runConcurrently(tasks);
145	
146	        long successes = results.stream().filter(r -> !(r instanceof Exception)).count();
147	        long conflicts = results.stream()
148	                .filter(r -> r instanceof ApiException ae && ae.status() == HttpStatus.CONFLICT)
149	                .count();
150	        assertThat(successes).isEqualTo(1);
151	        assertThat(conflicts).isEqualTo(1);
152	        Long active = jdbc.queryForObject(
