161	            String model = "m" + round;
162	            deviceService.register(new RegisterDeviceRequest("req-d" + round, deviceId, model, "1.0.0", 5));
163	            long releaseId = releaseService.create(
164	                    new CreateReleaseRequest("req-r" + round, model, "1.0.0", "2.0.0", 100)).releaseId();
165	            final int seq = round;
