        List<QuarantineRecordView> records = quarantineRecordRepository.findByDevice(deviceId).stream()
                .map(QuarantineRecordView::of).toList();
        return new QuarantineHistoryResponse(deviceId, records);
    }

    /**
     * 设备被拒回执列表（只读），按拒绝时间升序。
     */
