                .andExpect(jsonPath("$.records[0].operator").value("op-a"))
                .andExpect(jsonPath("$.records[0].reasonCode").value("HW_SUSPECT"))
                .andExpect(jsonPath("$.records[1].operation").value("UNQUARANTINE"))
