        quarantine("d1", "q4", "op-a", "HW", "1.0.0");

        // 重复隔离：409
        mockMvc.perform(post("/api/devices/d1/quarantine").contentType("application/json").content("""
                        {"requestId":"q5","operator":"op-a","reasonCode":"HW","expectedVersion":"1.0.0"}
