                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("DEVICE_NOT_QUARANTINED"));

        // 查询不存在设备的隔离历史与被拒回执：404
        mockMvc.perform(get("/api/devices/ghost/quarantines"))
