    @Test
    void 隔离幂等_同键重放首次结果_异参409_失败不占键() throws Exception {
        registerDevice("r1", "d1", "m1", "1.0.0", 1);
        registerDevice("r2", "d2", "m1", "1.0.0", 2);

        MvcResult first = mockMvc.perform(post("/api/devices/d1/quarantine")
