        // 历史取消不可改写：回执仍 409，拉取返回原 CANCELLED 任务
        mockMvc.perform(post("/api/tasks/" + taskId + "/receipt").contentType("application/json")
                        .content("{\"requestId\":\"r4\",\"result\":\"SUCCESS\"}"))
                .andExpect(status().isConflict())
